(()=>{'use strict';
const lang=window.platformLocale||'pt',locale=window.platformLocaleTag||'pt-BR';let ui=seed.ui[lang],projects=seed.projects,ideas=seed.ideas,central={itens:[]},content={};const id=x=>document.getElementById(x),own=(x,k)=>Object.prototype.hasOwnProperty.call(x,k);
const safe=x=>{try{const u=new URL(x);return u.protocol==='https:'?u.href:null;}catch(e){return null;}};
function local(item){return lang==='pt'?item:{...item,...(item.traducoes?.[lang]||{})};}
// Link availability is derived from data, not from a GitHub API query. A paused item stays paused.
function availability(item){const href=safe(item.link)||safe(item.repositorio);const status=String(item.status||'auto');if(status==='pausado')return {key:'pausado',label:ui.paused,href:null};if(status==='gravado')return {key:'gravado',label:ui.recorded,href:null};if(status==='em-producao'&&!href)return {key:'em-producao',label:ui.producing,href:null};if(status==='proposta'&&!href)return {key:'proposta',label:ui.proposal,href:null};if(href)return {key:'disponivel',label:ui.developed,href};if(['concluido','publicado','disponivel'].includes(status))return {key:'sem-link',label:ui.waitingLink,href:null};return {key:'em-desenvolvimento',label:ui.developing,href:null};}
function el(tag,text,cls){const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;}
function anchor(url,text){const a=el('a',text);a.href=url;if(!url.startsWith('#')){a.target='_blank';a.rel='noopener noreferrer';}return a;}
function card(item,project=false){const d=local(item),a=availability(item),n=el('article',null,'vitrine-card');n.append(el('span',a.label,'availability '+(a.href?'is-ready':'')),el('h3',d.titulo),el('p',d.descricao||''));if(a.href)n.append(anchor(a.href,project?ui.access:ui.open));const docs=safe(item.documentacao);if(docs)n.append(anchor(docs,ui.docs));return n;}
function fillList(target,values){const b=id(target);b.replaceChildren();for(const x of values)b.append(el('li',x));}
function renderProjects(){const q=id('project-search').value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const status=id('project-status').value,rows=projects.itens.filter(x=>x&&typeof x.titulo==='string');const filtered=rows.filter(x=>{const d=local(x);return (!status||availability(x).key===status)&&((d.titulo+' '+d.descricao).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q));});const box=id('project-grid');categorized(box,filtered,true);id('project-result').textContent=filtered.length?String(filtered.length)+' / '+rows.length:ui.noResults;id('home-projects').replaceChildren(...rows.slice(0,3).map(x=>card(x,true)));}
function renderIdeas(){categorized(id('social-ideas'),ideas.itens.filter(x=>x&&typeof x.titulo==='string'));}
function categorized(box,records,project=false){box.replaceChildren();for(const ready of [false,true]){const rows=records.filter(x=>['disponivel','sem-link','gravado'].includes(availability(x).key)===ready);if(!rows.length)continue;box.append(el('h2',ready?ui.readyGroup:ui.pendingGroup,'lifecycle-heading'));for(const item of rows)box.append(card(item,project));}}
function renderCentral(){window.pgeCentralCatalog=central.itens;window.dispatchEvent(new CustomEvent("pge-movies-changed"));const targets={filme:'filmes-desenhos',desenho:'filmes-desenhos',musica:'musicas',artigo:'artigos-estudos',estudo:'artigos-estudos',livro:'livros',palestra:'palestras',video:'palestras',curso:'escola',material:'biblioteca-ensino'};for(const section of new Set(Object.values(targets))){let box=id('central-'+section);const records=central.itens.filter(x=>x&&targets[x.tipo]===section&&typeof x.titulo==='string');if(!box&&records.length){box=el('div',null,'vitrine-grid');box.id='central-'+section;id(section).append(box);}if(box)categorized(box,records);}}
function renderSchool(data){const box=id('school-subjects');box.replaceChildren();for(const x of data.disciplinas||[]){const n=el('article',null,'vitrine-card');n.append(el('h2',x.titulo),el('p',x.fundamento),el('p',x.pergunta),anchor('#fe-conhecimento',ui.fundamentals));box.append(n);}}
function renderPartners(){const b=id('home-partners');b.replaceChildren();for(const x of content.partners||[]){if(!x?.titulo)continue;const n=el('article',null,'vitrine-card');n.append(el('h3',x.titulo),el('p',x.descricao||''),el('span',ui.partnerPending,'availability'),anchor('#parceiros',ui.communities));b.append(n);}if(!b.children.length)b.append(anchor('#seja-parceiro',ui.partnerAction));}
function renderParticipation(){fillList('home-care-topics',ui.careHighlights);const box=id('home-solidarity-items');box.replaceChildren();for(const [title,text] of ui.solidarityItems){const n=el('article',null,'vitrine-card');n.append(el('h3',title),el('p',text));box.append(n);}const qr=id('home-qr-slot');if(!qr.children.length){const source=document.querySelector('#doacoes .qr');if(source){const image=source.cloneNode(true);image.alt=ui.qrAlt;qr.append(image);}}else qr.querySelector('img').alt=ui.qrAlt;document.querySelectorAll('[data-contact-whatsapp]').forEach(a=>{a.href='https://wa.me/5566981295349';a.target='_blank';a.rel='noopener noreferrer';});}
function renderUI(){document.querySelectorAll('[data-v]').forEach(n=>{const v=ui[n.dataset.v];if(typeof v==='string')n.textContent=v;});document.querySelectorAll('[data-v-aria]').forEach(n=>n.setAttribute('aria-label',ui[n.dataset.vAria]));id('project-search').setAttribute('aria-label',ui.projectSearch);fillList('home-how-steps',ui.howSteps);const b=id('home-library');b.replaceChildren();for(const x of ui.libraryItems){const a=anchor('#'+x.id,'');a.className='vitrine-card vitrine-link';a.append(el('h3',x.titulo+' →'),el('p',x.descricao));b.append(a);}renderProjects();renderIdeas();renderCentral();renderPartners();renderParticipation();renderCalendar();}
function todayKey(){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Cuiaba',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(k=>p.find(x=>x.type===k).value).join('-');}
function date(key){return new Date(key+'T12:00:00');}function key(y,m,d){return y+'-'+String(m+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');}function serial(k){const [y,m,d]=k.split('-').map(Number);return Math.floor(Date.UTC(y,m-1,d)/86400000);}function wrap(n,len){return len?((n%len)+len)%len:0;}
let today=todayKey(),selected=today,view=date(today),following=true;
function renderCalendar(){id('home-month').textContent=view.toLocaleDateString(locale,{month:'long',year:'numeric'});const w=id('home-week');w.replaceChildren(...ui.week.map(x=>el('span',x)));const b=id('home-calendar-days');b.replaceChildren();const y=view.getFullYear(),m=view.getMonth();for(let n=0;n<new Date(y,m,1).getDay();n++){const blank=el('span');blank.setAttribute('aria-hidden','true');b.append(blank);}for(let d=1;d<=new Date(y,m+1,0).getDate();d++){const k=key(y,m,d),btn=el('button',String(d));btn.type='button';btn.setAttribute('aria-label',date(k).toLocaleDateString(locale,{day:'numeric',month:'long',year:'numeric'}));btn.setAttribute('aria-pressed',String(k===selected));if(k===today){btn.className='is-today';btn.setAttribute('aria-current','date');}btn.addEventListener('click',()=>{selected=k;following=k===today;renderCalendar();id('home-calendar-days').querySelector('[aria-pressed="true"]').focus();});b.append(btn);}renderDay();}
function renderDay(refreshPause=true){const entry=content.readings?.[selected]||{},n=serial(selected)-serial('2026-01-01');id('home-selected-date').textContent=date(selected).toLocaleDateString(locale,{weekday:'long',day:'numeric',month:'long',year:'numeric'});if(refreshPause&&window.pgeSelectPause)window.pgeSelectPause(selected);const prayers=content.prayers||[],reflections=content.reflections||[],songs=content.songs||[];id('home-prayer').textContent=entry.prayer||(prayers.length?prayers[wrap(n*791,prayers.length)]:({pt:'Senhor, guia minhas escolhas com amor e sabedoria. Amém.',en:'Lord, guide my choices with love and wisdom. Amen.',es:'Señor, guía mis decisiones con amor y sabiduría. Amén.'})[lang]);if(entry.reflection){id('home-daily-reflection').textContent=entry.reflection;id('home-daily-title').textContent=entry.reflectionTitle||ui.reflection;if(entry.step)id('home-daily-step').textContent=entry.step;const refs=Array.isArray(entry.reflectionPassages)?entry.reflectionPassages:Array.isArray(entry.passagens)?entry.passagens:[];const ref=refs.find(p=>safe(p.protestante)||safe(p.catolica)||safe(p.link));const a=id('home-daily-scripture');if(ref){a.href=safe(ref.protestante)||safe(ref.catolica)||safe(ref.link);a.textContent=(ref.referencia||ui.openPassage)+' ↗';a.hidden=false;}else{a.hidden=true;}}else{id('home-daily-scripture').hidden=false;}

const song=songs[wrap(n,songs.length)];id('home-song-title').textContent=entry.song||song?.titulo||({pt:'Louvor cristão para acompanhar a reflexão',en:'Christian worship for reflection',es:'Alabanza cristiana para reflexionar'})[lang];id('home-daily-song').href=(!entry.song&&safe(song?.link))||'https://www.youtube.com/results?search_query='+encodeURIComponent(id('home-song-title').textContent+' oficial');id('home-daily-song').textContent=ui.listen;
const reading=id('home-schedule-reading'),links=id('home-schedule-links');links.replaceChildren();reading.textContent=entry.reading||'';id('home-schedule-note').textContent=entry.reading?ui.scheduled:ui.pendingReading;for(const p of Array.isArray(entry.passagens)?entry.passagens:[]){for(const [field,edition] of [['protestante','ACF (PT)'],['catolica','Ave-Maria (PT)'],['link',''],['url','']]){const href=safe(p[field]);if(href)links.append(anchor(href,(p.referencia||p.reference||p.titulo||ui.openPassage)+(edition?' · '+edition:'')));}}if(!entry.reading){const editorial=id('home-daily-scripture');if(safe(editorial.href))links.append(anchor(editorial.href,editorial.textContent));}else if(!links.children.length){links.append(anchor('https://www.bibliaonline.com.br/acf',ui.openPassage));}
// No invented verse: original authorial reflection is labelled; exact verses come from verified user records.
}
document.querySelectorAll('#inicio a[href="#estudo-diario"]').forEach(a=>a.addEventListener('click',()=>window.dispatchEvent(new CustomEvent('pge-date-select',{detail:selected}))));id('project-search').addEventListener('input',renderProjects);id('project-status').addEventListener('change',renderProjects);id('home-month-prev').addEventListener('click',()=>{view=new Date(view.getFullYear(),view.getMonth()-1,1);renderCalendar();});id('home-month-next').addEventListener('click',()=>{view=new Date(view.getFullYear(),view.getMonth()+1,1);renderCalendar();});id('home-calendar-today').addEventListener('click',()=>{today=todayKey();selected=today;following=true;view=date(today);renderCalendar();});
window.addEventListener('pge-pause-updated',()=>renderDay(false));window.addEventListener('content-data',e=>{Object.assign(content,e.detail);renderPartners();renderDay();});window.addEventListener('pge-bootstrap',e=>{Object.assign(content,e.detail);renderPartners();renderDay();});
async function load(){if(!['http:','https:'].includes(location.protocol))return;const specs=[['ui','pagina-inicial.json'],['projects','projetos.json'],['ideas','ideias-sociais.json'],['central','catalogo-conteudos.json'],['school','fe-conhecimento.json']];const values=await Promise.allSettled(specs.map(async([k,name])=>{const response=await fetch('dados/'+name,{cache:'no-store'});if(!response.ok)throw Error(name);return [k,await response.json()];}));for(const x of values){if(x.status!=='fulfilled')continue;const [k,v]=x.value;if(k==='ui'&&Array.isArray(v.libraryItems)&&Array.isArray(v.howSteps)&&Array.isArray(v.week)&&Object.keys(ui).every(key=>typeof v[key]===typeof ui[key]))ui=v;else if(k==='projects'&&Array.isArray(v.itens))projects=v;else if(k==='ideas'&&Array.isArray(v.itens))ideas=v;else if(k==='central'&&Array.isArray(v.itens))central=v;else if(k==='school')renderSchool(v);}renderUI();}
function tick(){const k=todayKey();if(k!==today){today=k;if(following){selected=k;view=date(k);}renderCalendar();}}
renderUI();renderSchool(seed.school[lang]);load();setInterval(tick,60000);setInterval(load,300000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){tick();load();}});
window.pgeCatalogAvailability=availability;
})();
